struct AddVersionHeaderMiddleware: Middleware {
    func respond(to request: Request, chainingTo next: Responder) -> EventLoopFuture<Response> {
        next.respond(to: request).map { response in          // handler + inner middleware
            response.headers.add(name: "My-App-Version", value: "v2.5.9")   // post
            return response
        }
    }
}
app.middleware.use(AddVersionHeaderMiddleware())

